from tradingview_scraper.symbols.ideas import Ideas

ideas_scraper = Ideas(export_result=False)

forex_pairs = ['EURUSD', 'GBPUSD', 'USDJPY', 'XAUUSD']
for pair in forex_pairs:
    ideas = ideas_scraper.scrape(
        symbol=pair,
        startPage=1,
        endPage=2,
        sort='recent'
    )
    # Process ideas - extract direction/bias from titles
    for idea in ideas:
        title = idea.get('title', '').lower()
        if 'long' in title or 'buy' in title or 'bullish' in title:
            bias = 'LONG'
        elif 'short' in title or 'sell' in title or 'bearish' in title:
            bias = 'SHORT'
        else:
            bias = 'NEUTRAL'
